// The web Worker's entry: the one public entry point on Cloudflare. API paths go to the API Worker
// over its service binding, unchanged, so cookies stay first-party and Epic, the browser and the
// VPS keep using /api/* on the same origin. Everything else is the Next app (OpenNext).
// Plan: docs/superpowers/plans/2026-10-30-cloudflare-migration.md
// @ts-expect-error: generated by `opennextjs-cloudflare build`.
import { default as nextApp } from "../.open-next/worker.js";

type Env = { API: { fetch(request: Request): Promise<Response> } };

export function isApiPath(pathname: string): boolean {
  return pathname === "/api" || pathname.startsWith("/api/");
}

const worker = {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    // cf-connecting-ip comes with the request from Cloudflare's edge and is passed on as is: the
    // API's rate limits key on it.
    if (isApiPath(new URL(request.url).pathname)) return env.API.fetch(request);
    return nextApp.fetch(request, env, ctx);
  },
};

export default worker;
